function downloadCsv(name: string, rows: Record<string, unknown>[]) {

  const keys = Object.keys(rows[0] || { status: "No data" });
  const cell = (value: unknown) => { const text = String(value ?? ''); return '"' + (text.match(/^[=+@-]/) ? "'" + text : text).replaceAll('"', '""') + '"'; };
  const blob = new Blob(['\ufeff' + [keys.map(cell).join(','), ...rows.map((r) => keys.map((k) => cell(r[k])).join(','))].join('\r\n')], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url);
  useProduct.getState().notify("CSV report exported with its provenance.");

}

export function PageHeading({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: React.ReactNode }) { return <div className="p-page-heading"><div><span className="p-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action && <div className="p-heading-actions">{action}</div>}</div>; }

export function Layers() {
  const layers = useProduct(state => state.layers);
  const observed = useProduct(state => state.mode === 'observed');
  return <div className="p-layer-controls">{[['congestion', observed ? 'Road network' : 'Traffic', 'route'], ['cameras', 'Cameras', 'camera'], ['incidents', 'Signals', 'alert'], ['pedestrians', 'Pedestrians', 'walk'], ['freight', 'Freight', 'car']].map(([key, label, icon]) => {
    const unavailable = observed && (key === 'pedestrians' || key === 'freight');
    return <button key={key} disabled={unavailable} title={unavailable ? 'Available in presentation mode; no calibrated observations are available.' : label} className={layers[key] && !unavailable ? 'active' : ''} aria-pressed={layers[key] && !unavailable} onClick={() => useProduct.getState().toggleLayer(key)}><Icon name={icon} size={15} />{label}<i /></button>;
  })}</div>;
}

export function Overview({ mapOnly = false }: { mapOnly?: boolean }) {

  const cameras = useProduct((s) => s.cameras);
  const cases = useProduct((s) => s.cases);
  const mode = useProduct((s) => s.mode);
  const district = useProduct((s) => s.district);
  const query = useProduct((s) => s.query);
  const status = useStore((s) => s.graphStatus);
  const mapFocus = useProduct((s) => s.mapFocus);
  const zoneCameras = cameras.filter(c => matchesZone(district, c.district));
  const scopedCases = cases.filter(c => c.data_origin === (mode === 'presentation' ? 'presentation' : 'observation') && (district === "All districts" || (c.data_origin === 'observation' ? zoneCameras.some(camera => camera.id === c.evidence_camera_id) : signals.some(signal => signal.id === c.signal_id && matchesZone(district, signal.district)))));
  const visible = mode === 'presentation' ? signals.filter((s) => matchesZone(district, s.district) && `${s.title} ${s.location}`.toLowerCase().includes(query.toLowerCase())) : [];
  return <div className={`p-screen p-overview ${mapOnly ? 'map-only' : ''}`}>
    <PageHeading eyebrow="MOBILITY INTELLIGENCE" title={mapOnly ? "The region in context" : "A clearer region."} subtitle="Greater Los Angeles, California · coast, valley and regional corridors." action={<button className="p-button primary" onClick={() => useProduct.getState().navigate('/explore')}>Explore a street <Icon name="search" /></button>} />
    {!mapOnly && <div className="p-metrics four"><MetricCard label="Public cameras" value={cameras.length ? zoneCameras.length : '—'} unit="sources" icon="camera" note="Caltrans · free access" /><MetricCard label="Road network" value={status?.edge_count.toLocaleString("en-US") || '—'} unit="segments" icon="route" note={status?.is_synthetic ? "Illustrative network" : "OpenStreetMap · real network"} /><MetricCard label="Review needed" value={mode === 'presentation' ? visible.filter((s) => !cases.some((c) => c.signal_id === s.id && ['resolved', 'dismissed'].includes(c.status))).length : scopedCases.filter((c) => !['resolved', 'dismissed'].includes(c.status)).length} icon="alert" tone="amber" note={mode === 'presentation' ? "Scenario signals" : "Observed cases"} /><MetricCard label="Confirmed cases" value={scopedCases.filter((c) => c.status === 'confirmed').length} icon="check" note="Operator confirmation" /></div>}
    <div className="p-region-explorer" aria-label="Explore areas"><button className={district === "All districts" ? 'active' : ''} onClick={() => { useProduct.getState().setMapFocus(null); useProduct.getState().setDistrict("All districts"); }}>Entire region <b>{cameras.length}</b></button>{regions.map(region => <button key={region.name} className={district === region.name ? 'active' : ''} onClick={() => { useProduct.getState().setMapFocus(null); useProduct.getState().setDistrict(region.name); }}><Icon name="pin" size={13} />{region.name}<b>{cameras.filter(c => matchesZone(region.name, c.district)).length}</b></button>)}</div>
    <div className={`p-overview-layout ${mapOnly ? 'map-only' : ''}`}><section className="p-overview-map"><Layers /><CityMap focus={mapOnly && mapFocus ? mapFocus : undefined} />{!mapOnly && <div className="p-map-story"><Badge>{mode === 'presentation' ? "Explore the scenario" : "Public sources"}</Badge><h3>Context changes<br />the decision.</h3><p>Select a segment, camera or signal to open its evidence.</p><button className="p-text-button" onClick={() => useProduct.getState().navigate('/corridors/harbor')}>Explore the corridor <Icon name="arrow" size={15} /></button></div>}</section>
      {!mapOnly && <aside className="p-mobility-sidebar"><Panel title="City pulse" action={<span className="p-live-dot">{mode === 'presentation' ? "Scenario" : "Operations"}</span>}><div className="p-signal-cards">{visible.slice(0, 4).map((signal) => <button key={signal.id} className="p-signal-card" onClick={() => { useProduct.getState().selectSignal(signal.id); useProduct.getState().navigate('/hotspots'); }}><div className={`p-signal-icon ${signal.severity}`}><Icon name={signal.type === "Pedestrians" ? 'walk' : signal.type === "Freight" ? 'car' : 'alert'} size={22} /></div><div><span><b>{signal.title}</b><SeverityBadge value={signal.severity} /></span><small><Icon name="pin" size={11} />{signal.location}</small><p>{signal.evidence}</p><Sparkline tone={signal.severity === 'high' ? 'red' : 'amber'} /></div></button>)}{!visible.length && <EmptyState title={query ? "No matches" : "No review signals"} detail={mode === 'observed' ? "A traffic image does not confirm incidents. Create a case only after reviewing its evidence." : "Try another district or search."} />}</div><button className="p-text-button" onClick={() => useProduct.getState().navigate('/risk-signals')}>View review queue <Icon name="arrow" size={14} /></button></Panel><Panel title="Window into the city" action={<button className="p-text-button" onClick={() => useProduct.getState().navigate('/cameras')}>View all</button>}><div className="p-preview-grid">{cameras.filter(c => matchesZone(district, c.district)).sort((a, b) => Number(cameraStatus(b).usable) - Number(cameraStatus(a).usable)).slice(0, 2).map((camera) => <CameraThumb key={camera.id} camera={camera} />)}</div><p className="p-small-note">Public Caltrans video sources. Availability depends on the provider.</p></Panel></aside>}
    </div>
    {!mapOnly && <CoverageDashboard />}
    {!mapOnly && <div className="p-overview-footer"><span><Icon name="shield" size={16} />Aggregate intelligence. Decisions remain with the operator.</span><button className="p-text-button" onClick={() => useProduct.getState().navigate('/storyboard')}>How FlowSense works <Icon name="arrow" size={14} /></button></div>}
  </div>;

}

export function Hotspots({ risk = false }: { risk?: boolean }) {

  const mode = useProduct((s) => s.mode);
  const district = useProduct((s) => s.district);
  const query = useProduct((s) => s.query);
  const selectedId = useProduct((s) => s.selectedSignal);
  const cameras = useProduct((s) => s.cameras);
  const cases = useProduct((s) => s.cases);
  const scopedCases = cases.filter((c) => c.data_origin === (mode === 'presentation' ? 'presentation' : 'observation'));
  const [severity, setSeverity] = useState('all');
  const [type, setType] = useState('all');
  const [confidence, setConfidence] = useState(0);
  const [reviewStatus, setReviewStatus] = useState('all');
  const [sort, setSort] = useState('impact');
  const [dialog, setDialog] = useState<Signal | null>(null);
  const observedSignals: Signal[] = cases.filter((c) => c.data_origin === 'observation').map((c) => { const cameraIndex = cameras.findIndex((cam) => cam.id === c.evidence_camera_id); const camera = cameras[cameraIndex]; return { id: c.signal_id, title: c.evidence_session_id ? "Manual video review" : "Manual image review", location: camera?.name || c.title, district: camera?.district || 'Los Angeles', type: "Manual review", severity: c.severity, confidence: c.confidence ?? null, impact: 0, evidence: "Public camera observation", duration: 0, lat: camera?.lat ?? 34.048, lng: camera?.lng ?? -118.259, action: c.note, owner: c.owner, cameraIndex: Math.max(cameraIndex, 0), causes: [c.evidence_session_id ? "A video session prompted a manual review." : "The public image prompted a manual review.", "Detections do not confirm a cause or an incident."], data_origin: 'observation', evidence_camera_id: c.evidence_camera_id || undefined, evidence_frame_id: c.evidence_frame_id || undefined }; });
  const items = (mode === 'presentation' ? signals : observedSignals).filter((s) => matchesZone(district, s.district) && (severity === 'all' || severity === s.severity) && (type === 'all' || type === s.type) && (s.confidence ?? 0) * 100 >= confidence && `${s.title} ${s.location} ${s.id}`.toLowerCase().includes(query.toLowerCase()) && (reviewStatus === 'all' || (cases.find((c) => c.signal_id === s.id)?.status || 'new') === reviewStatus)).sort((a, b) => sort === 'confidence' ? (b.confidence ?? 0) - (a.confidence ?? 0) : sort === 'duration' ? b.duration - a.duration : b.impact - a.impact);
  const selected = items.find((s) => s.id === selectedId) || items[0];
  const selectedCase = cases.find((c) => c.signal_id === selected?.id);
  const focus: [number, number] | undefined = selected ? [selected.lat, selected.lng] : undefined;
  return <div className="p-screen p-queue-screen">
    <PageHeading eyebrow={risk ? "EVIDENCE BEFORE ACTION" : "CITY PRIORITIES"} title={risk ? "Risk signals" : "Hotspots"} subtitle={risk ? "Review what changed. Check the evidence before confirming." : "Where to look first, ranked by impact and evidence."} action={<button className="p-button" onClick={() => downloadCsv(risk ? 'flowsense-risk-signals.csv' : 'flowsense-hotspots.csv', items.map((s) => ({ id: s.id, location: s.location, issue: s.title, severity: s.severity, confidence_score: s.confidence, status: cases.find((c) => c.signal_id === s.id)?.status || 'new', data_origin: s.data_origin || 'presentation' })))}><Icon name="download" />Export</button>} />
    <div className="p-filter-bar"><label>Type<select value={type} onChange={(e) => setType(e.target.value)}><option value="all">All types</option>{[...new Set([...signals.map((s) => s.type), "Manual review"])].map((t) => <option key={t}>{t}</option>)}</select></label><label>Priority<select value={severity} onChange={(e) => setSeverity(e.target.value)}><option value="all">All priorities</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label>{risk && <label>Minimum score {confidence}%<input type="range" min="0" max="100" value={confidence} onChange={(e) => setConfidence(Number(e.target.value))} /></label>}<label>Review<select value={reviewStatus} onChange={(e) => setReviewStatus(e.target.value)}><option value="all">All statuses</option>{Object.entries(statusLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Sort by<select value={sort} onChange={(e) => setSort(e.target.value)}><option value="impact">Impact · highest first</option><option value="confidence">Evidence score</option><option value="duration">Duration</option></select></label><span className="p-filter-count">{items.length}  signals</span></div>
    <div className={`p-queue-layout ${risk ? 'risk' : ''}`}>
      {risk && <section className="p-risk-map"><CityMap focus={focus} compact selected={selected?.id} signalItems={items} onSignal={(s) => useProduct.getState().selectSignal(s.id)} /><div className="p-risk-map-key"><span><i className="red" />High priority</span><span><i className="amber" />Review required</span></div></section>}
      <section className="p-panel p-table-panel"><div className="p-panel-head"><h3>{risk ? "Review queue" : "Ranked by impact"}</h3><Badge tone="gray">{useProduct.getState().period}</Badge></div>{items.length ? <div className="p-table-scroll"><table className="p-table"><thead><tr><th>#</th><th>{risk ? "Signal / location" : "Location / signal"}</th><th>Priority</th><th>{risk ? 'Score' : "Evidence"}</th>{!risk && <th>Impact</th>}<th>{risk ? "Duration" : 'Score'}</th><th>Status</th></tr></thead><tbody>{items.map((signal, i) => <tr key={signal.id} className={selected?.id === signal.id ? 'selected' : ''} onClick={() => useProduct.getState().selectSignal(signal.id)} tabIndex={0} aria-selected={selected?.id === signal.id} onKeyDown={(e) => { if (e.key === 'Enter') useProduct.getState().selectSignal(signal.id); }}><td>{i + 1}</td><td><div className="p-table-location">{!risk && <CameraThumb camera={cameras[signal.cameraIndex % Math.max(cameras.length, 1)]} />}<div><b>{risk ? signal.title : signal.location}</b><small>{risk ? signal.location : signal.title} · {signal.district}</small></div></div></td><td><SeverityBadge value={signal.severity} /></td><td>{risk ? <ConfidenceMeter value={signal.confidence} /> : <><span>{signal.evidence}</span><Sparkline tone={signal.severity === 'high' ? 'red' : 'amber'} /></>}</td>{!risk && <td><b className={signal.severity === 'high' ? 'p-red' : 'p-amber'}>{signal.data_origin === 'observation' ? "No baseline" : `↑ +${signal.impact}%`}</b><small>{signal.data_origin === 'observation' ? "No measured comparison" : "vs. illustrative baseline"}</small></td>}<td>{risk ? signal.data_origin === 'observation' ? "Manual review" : `${signal.duration} min` : <ConfidenceMeter value={signal.confidence} />}</td><td><ReviewBadge value={cases.find((c) => c.signal_id === signal.id)?.status || 'new'} /></td></tr>)}</tbody></table></div> : <EmptyState title="No signals in this view" detail={mode === 'observed' ? "No real signals have been received. Public cameras in the seven areas can be queried in Evidence." : "Change the filters to broaden your search."} />}<div className="p-table-foot"><span>{items.length}  results · scores are not calibrated probabilities.</span><button className="p-text-button" onClick={() => { setSeverity('all'); setType('all'); setConfidence(0); setReviewStatus('all'); useProduct.getState().setDistrict("All districts"); }}>Reset filters</button></div></section>
      <aside className="p-detail-drawer">{selected ? <><header><div className={`p-detail-rank ${selected.severity}`}>{items.indexOf(selected) + 1}</div><div><h2>{selected.title}</h2><p><Icon name="pin" size={12} />{selected.location}</p></div></header>{!risk && <div className="p-detail-map"><CityMap focus={focus} compact selected={selected.id} /></div>}<div className="p-detail-metrics"><span>Priority<SeverityBadge value={selected.severity} /></span><span>Score<ConfidenceMeter value={selected.confidence} /></span><span>{selected.data_origin === 'observation' ? "Source" : "Duration"}<b>{selected.data_origin === 'observation' ? "Public camera" : selected.duration + ' min'}</b></span></div><Panel title="Camera evidence" action={<Badge tone="gray">Public source</Badge>}><div className="p-evidence-strip">{[0, 1, 2].map((offset) => <CameraThumb key={offset} camera={cameras[(selected.cameraIndex + offset) % Math.max(cameras.length, 1)]} />)}</div><p className="p-small-note">{selected.data_origin === 'observation' ? "Case opened by an operator from a real observation. It does not independently confirm an incident. An image queried in the session is not a provider archive." : "The images are real; the signal and its metrics are illustrative. They do not prove that this incident is occurring."}</p></Panel><Panel title="Why it needs attention"><p className="p-detail-description">{selected.action}</p><ul className="p-cause-list">{selected.causes.map((cause) => <li key={cause}>{cause}</li>)}</ul></Panel><Panel title="Next check"><div className="p-next-check"><Icon name="search" /><p>Query the camera, compare the context and document the review before acting.</p></div></Panel>{selectedCase && <div className="p-case-summary"><span>{selectedCase.id}</span><ReviewBadge value={selectedCase.status} /><small>{selectedCase.owner} · {selectedCase.audit.length}  audit log entries</small></div>}<div className="p-review-actions"><button className="p-button primary" onClick={() => setDialog(selected)}><Icon name="check" />{selectedCase && ['resolved', 'dismissed'].includes(selectedCase.status) ? "View audit log" : selectedCase ? "Continue review" : "Assign review"}</button><button className="p-button" onClick={() => useProduct.getState().navigate(`/cameras/${cameras[selected.cameraIndex % Math.max(cameras.length, 1)]?.id || ''}`)}><Icon name="camera" />Open evidence</button></div></> : <EmptyState title="Select a signal" detail="Its details and evidence appear here." />}</aside>
    </div>
    {risk && <div className="p-metrics four p-queue-kpis"><MetricCard label={mode === 'presentation' ? "Scenario signals" : "Camera cases"} value={mode === 'presentation' ? signals.length : observedSignals.length} icon="alert" /><MetricCard label="Assigned cases" value={scopedCases.filter((c) => c.status === 'assigned').length} icon="clock" /><MetricCard label="Confirmed by operator" value={scopedCases.filter((c) => c.status === 'confirmed').length} icon="check" /><MetricCard label="Dismissed" value={scopedCases.filter((c) => c.status === 'dismissed').length} icon="shield" /></div>}
    {dialog && <CaseDialog signal={dialog} onClose={() => setDialog(null)} />}
  </div>;

}

export function CorridorAnalytics({ id }: { id?: string }) {

  const corridor = corridors.find((c) => c.id === id) || corridors[0];
  const cameras = useProduct((s) => s.cameras);
  const mode = useProduct((s) => s.mode);
  const period = useProduct((s) => s.period);
  const [baseline, setBaseline] = useState(true);
  const [segment, setSegment] = useState(1);
  const roadEdges = useStore((s) => s.geojsonEdges);
  const corridorEdges = useMemo(() => {
    const names: Record<string, string> = { harbor: 'Harbor Freeway', hollywood: 'Hollywood Freeway', 'santa-monica': 'Santa Monica Freeway' };
    const seen = new Set<string>();
    return roadEdges.filter(edge => {
      const key = [edge.properties.u, edge.properties.v].sort().join('-');
      if (edge.geometry.type !== 'LineString' || edge.properties.name !== names[corridor.id] || seen.has(key)) return false;
      seen.add(key); return true;
    }).sort((a, b) => {
      const point = (edge: typeof a) => edge.geometry.type === 'LineString' ? Math.hypot(edge.geometry.coordinates[0][1] - corridor.lat, edge.geometry.coordinates[0][0] - corridor.lng) : Infinity;
      return point(a) - point(b);
    });
  }, [roadEdges, corridor.id, corridor.lat, corridor.lng]);
  const realSegments = corridorEdges.slice(0, 7);
  const activeSegment = Math.min(segment, Math.max(realSegments.length, 1));
  const selectedEdge = realSegments[activeSegment - 1];
  const nearbyCameras = useMemo(() => [...cameras].sort((a, b) => Math.hypot(a.lat - corridor.lat, a.lng - corridor.lng) - Math.hypot(b.lat - corridor.lat, b.lng - corridor.lng)), [cameras, corridor.lat, corridor.lng]);
  const example = mode === 'presentation';
  const factor = period === "Last 15 min" ? 1 : period === "Last hour" ? .87 : period === "Last 24 h" ? .73 : .65;
  const speedValue = Math.round(corridor.speed + (1 - factor) * 12);
  const change = (current: number, base: number) => `${current >= base ? '\u2191' : '\u2193'} ${Math.round(Math.abs(current / base - 1) * 100)}% vs. baseline`;
  const delta = (current: number, base: number) => example && baseline ? change(current, base) : undefined;
  return <div className="p-screen"><PageHeading eyebrow="CORRIDOR DIAGNOSTICS" title={corridor.name} subtitle={`${corridor.length} reference km · ${corridor.intersections} intersections · ${corridor.district}`} action={<><select className="p-select" value={corridor.id} onChange={(e) => useProduct.getState().navigate(`/corridors/${e.target.value}`)}>{corridors.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select><label className="p-toggle-label"><input type="checkbox" checked={baseline} onChange={(e) => setBaseline(e.target.checked)} />Compare baseline</label><button className="p-button" onClick={() => downloadCsv('flowsense-corridor.csv', trendSeries(factor).map((row) => ({ corridor: corridor.name, data_origin: 'presentation', period, ...row })))} disabled={!example}><Icon name="download" />Export</button></>} />
    <div className="p-analytics-layout"><div><div className="p-corridor-map"><CityMap focus={[corridor.lat, corridor.lng]} highlight={selectedEdge} viewEdges={corridorEdges} /><div className="p-corridor-caption"><Badge>{corridor.district}</Badge><b>Segment {activeSegment.toString().padStart(2, '0')}</b><span>{example ? "Illustrative congestion " + (corridor.congestion * factor).toFixed(2) : "No calibrated traffic counts"}</span></div></div><div className="p-segment-selector">{realSegments.map((edge, i) => <button key={`${edge.properties.u}-${edge.properties.v}`} aria-pressed={activeSegment === i + 1} title={`${edge.properties.name} · ${Math.round(edge.properties.length ?? 0)} m`} onClick={() => setSegment(i + 1)} className={activeSegment === i + 1 ? 'active' : ''}><i style={{ background: i === 2 || i === 3 ? '#ce8a74' : i === 4 ? '#d2b36a' : '#82a684' }} />Segment {i + 1}</button>)}</div><div className="p-metrics five"><MetricCard note={example ? "Scenario without comparison" : "No calibrated measurement"} label="Congestion" value={example ? (corridor.congestion * factor).toFixed(2) : '—'} delta={delta(corridor.congestion * factor, corridor.congestion / 1.22)} tone="red" /><MetricCard note={example ? "Scenario without comparison" : "No calibrated measurement"} label="Average speed" value={example ? speedValue : '\u2014'} unit="km/h" delta={delta(speedValue, corridor.speed / .82)} /><MetricCard note={example ? "Scenario without comparison" : "No calibrated measurement"} label="Freight pressure" value={example ? Math.round(corridor.truck * factor) : '\u2014'} unit="/100" delta={delta(corridor.truck * factor, corridor.truck / 1.75)} tone="amber" /><MetricCard note={example ? "Scenario without comparison" : "No calibrated measurement"} label="Pedestrian crossings" value={example ? (corridor.pedestrians * factor / 1000).toFixed(1) + 'k' : '—'} unit="/day" delta={delta(corridor.pedestrians * factor, corridor.pedestrians / 1.28)} /><MetricCard note={example ? "Scenario without comparison" : "No calibrated measurement"} label="Estimated queue" value={example ? Math.round(corridor.queue * factor) : '\u2014'} unit="m" delta={delta(corridor.queue * factor, corridor.queue / 1.68)} tone="red" /></div>
    {example ? <div className="p-chart-grid"><Panel title="Hourly congestion" action={<span className="p-chart-key">Period{baseline && " / baseline"}</span>}><TrendChart baseline={baseline} factor={factor} /></Panel><Panel title="Speed trend"><TrendChart metric="speed" baseline={baseline} factor={factor} /></Panel><Panel title="Traffic composition"><div className="p-stack-comparison">{["This period", ...(baseline ? ["Baseline"] : [])].map((label, i) => <div key={label}><span>{label}</span><div className="p-stacked-bar">{[72 - i * 4, 14 + i * 4, 9, 5].map((value, j) => <span key={j} style={{ width: `${value}%`, background: Object.values(classColors)[j] }}>{value}%</span>)}</div></div>)}<div className="p-mix-key">{Object.entries(classLabels).slice(0, 4).map(([key, label]) => <span key={key}><i style={{ background: classColors[key] }} />{label}</span>)}</div></div></Panel><Panel title="Pedestrian demand"><TrendChart metric="pedestrians" bars height={150} /></Panel></div> : <EmptyState title="The camera does not provide a baseline" detail="A series of traffic counts and road calibration is required to estimate speeds, queues and changes over time." />}</div><aside className="p-analytics-insights"><Panel title="What changed" action={<Icon name="info" size={16} />}>{example ? <div className="p-insight-list">{[["More peak-hour pressure", "Demand in the illustrative period increases at corridor access points."], ["Greater freight presence", "The example increases the relative share of trucks; review access conditions."], ["More crossing demand", "Compare crossing windows and accessibility conditions."]].map(([title, text], i) => <div key={title}><b>{i + 1}</b><section><h4>{title}</h4><p>{text}</p></section></div>)}</div> : <p className="p-small-note">No real comparison between periods is available yet.</p>}<div className="p-insight-action"><h4>Next check</h4><p>Review the public access image before attributing a cause.</p><button className="p-button primary" onClick={() => useProduct.getState().navigate(`/cameras/${nearbyCameras[0]?.id || ''}`)}>Check evidence <Icon name="arrow" /></button></div></Panel><Panel title="Nearby cameras"><p className="p-small-note">Sorted by proximity to the corridor; they do not establish coverage of each segment.</p><div className="p-preview-grid">{nearbyCameras.slice(0, 2).map((c) => <CameraThumb key={c.id} camera={c} />)}</div></Panel></aside></div>
  </div>;

}

export function Pedestrians() {

  const cameras = useProduct((s) => s.cameras);
  const mode = useProduct((s) => s.mode);
  const [zone, setZone] = useState(0);
  const [transport, setTransport] = useState("Pedestrians");
  const zones = [signals[2], signals[7], signals[4]];
  const selected = zones[zone];
  const example = mode === 'presentation';
  return <div className="p-screen"><PageHeading eyebrow="MOBILITY AT HUMAN SCALE" title="Pedestrian flow" subtitle="Aggregate demand, crossings and context for reviewing road safety." action={<><select className="p-select" value={zone} onChange={(e) => setZone(Number(e.target.value))}>{zones.map((s, i) => <option key={s.id} value={i}>{s.location}</option>)}</select><div className="p-segmented">{["Vehicles", "Pedestrians", "Cyclists", "Transit"].map((t) => <button key={t} className={transport === t ? 'active' : ''} onClick={() => setTransport(t)}>{t}</button>)}</div></>} /><div className="p-pedestrian-layout"><section className="p-pedestrian-map"><CityMap focus={[selected.lat, selected.lng]} pedestrians={transport === "Pedestrians"} /><div className="p-zone-label"><Icon name="walk" size={22} /><span><b>{selected.location}</b><small>{transport} · {selected.district}</small></span></div><div className="p-zone-context"><Icon name="pin" /><span>Scenario context<br /><b>{zone === 0 ? "Civic center" : zone === 1 ? "Commercial crossing" : "Corridor access"}</b></span></div></section><aside><Panel title={`Signals · ${transport}`}><div className="p-metrics two"><MetricCard label={transport === "Pedestrians" ? "Crossing demand" : "Mode demand"} value={example ? [1420, 860, 650][zone] : '—'} unit="/hora" icon="walk" delta={example ? "↑ 18% vs. baseline" : undefined} /><MetricCard label="Space pressure" value={example ? (.76 - zone * .09).toFixed(2) : '—'} icon="alert" tone="amber" delta={example ? "High-demand scenario" : undefined} /><MetricCard label="Estimated wait" value={example ? 28 + zone * 4 : '—'} unit="s" icon="clock" delta={example ? "↓ 12% vs. baseline" : undefined} /><MetricCard label="Interactions to review" value={example ? 14 - zone * 2 : '—'} unit="/hora" tone="red" delta={example ? "↑ 27% vs. baseline" : undefined} /></div><div className="p-accessibility"><Icon name="shield" size={26} /><span><b>Accessibility check</b><small>Review crossing times, continuity and conditions.</small></span><Badge tone="amber">Pending</Badge></div></Panel></aside></div><div className="p-pedestrian-charts"><Panel title="Hourly volume">{example ? <TrendChart metric="pedestrians" bars /> : <EmptyState />}</Panel><Panel title="Crossings within the signal phase">{example ? <><div className="p-compliance"><div className="p-donut" style={{ background: 'conic-gradient(#668e69 0% 92%, #d2b266 92% 98%, #c87566 98%)' }}><div><b>92%</b><small>scenario</small></div></div><ul><li><i className="green" />Within phase <b>92%</b></li><li><i className="amber" />Late crossing <b>6%</b></li><li><i className="red" />Outside phase <b>2%</b></li></ul></div><p className="p-small-note">Measuring compliance requires integration with the actual traffic signal phase.</p></> : <EmptyState />}</Panel><Panel title="Potential interactions">{example ? <TrendChart metric="conflicts" bars /> : <EmptyState />}</Panel><Panel title="Check evidence"><CameraThumb camera={cameras[zone % Math.max(1, cameras.length)]} /><p className="p-small-note">A potential interaction does not confirm an accident. Human review required.</p></Panel></div></div>;

}

export function EmergencyCorridor() {

  const cameras = useProduct((s) => s.cameras);
  const route = useStore((s) => s.activeRoute);
  const options = useStore((s) => s.routeOptions);
  const [origin, setOrigin] = useState(() => { const point = route?.waypoints[0]; return point ? `${point.latitude},${point.longitude}` : '34.0437,-118.2505'; });
  const [destination, setDestination] = useState(() => { const point = route?.waypoints.at(-1); return point ? `${point.latitude},${point.longitude}` : '34.0533,-118.2657'; });
  const [vehicle, setVehicle] = useState<'ambulance' | 'fire_truck'>(() => route?.vehicle_type === 'fire_truck' ? 'fire_truck' : 'ambulance');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const assessment = useStore(state => state.routeResilience);
  const [pick, setPick] = useState<'origin' | 'destination' | null>(null);
  const mapSection = useRef<HTMLDivElement>(null);
  useEffect(() => { if (pick) mapSection.current?.scrollIntoView({ block: 'center', behavior: 'smooth' }); }, [pick]);

  const calculate = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const response = await computeAlternativeRoutes({ origin: parseCoordinates(origin), destination: parseCoordinates(destination), vehicle_type: vehicle, priority: 'high' });
      useStore.getState().setActiveRoute(response.primary); useStore.getState().setRouteOptions([response.primary, ...response.alternatives]);
      useStore.getState().setRouteResilience(response.resilience ?? null);
      useProduct.getState().notify("Corridor calculated using the road network and confirmed restrictions.");
    } catch (error) { setError(error instanceof Error ? error.message : "No route found."); }
    finally { setBusy(false); }
  };
  const routePoints = route?.waypoints || [];
  const checkpoints = cameras.filter((c) => routePoints.some((wp) => Math.hypot((wp.latitude - c.lat) * 111139, (wp.longitude - c.lng) * 92000) < 700)).slice(0, 5);
  const eta = route ? route.total_estimated_time_s / 60 : null;
  return <div className="p-screen"><PageHeading eyebrow="EMERGENCY DECISION SUPPORT" title="One corridor. One backup." subtitle="Compare routes and review evidence near the journey." action={<Badge tone="green">Real road network · OSM</Badge>} /><form className="p-dispatch-form" onSubmit={(e) => void calculate(e)}><label>Unit<select value={vehicle} onChange={(e) => setVehicle(e.target.value as typeof vehicle)}><option value="ambulance">Ambulance</option><option value="fire_truck">Fire truck</option></select></label><label>Origin · latitude,longitude<input aria-label="Origin coordinates" required value={origin} onChange={(e) => setOrigin(e.target.value)} /><button type="button" className="p-pick-button" onClick={() => setPick('origin')} aria-label="Choose origin on map"><Icon name="pin" size={14} /></button></label><Icon name="arrow" /><label>Destination · latitude,longitude<input aria-label="Destination coordinates" required value={destination} onChange={(e) => setDestination(e.target.value)} /><button type="button" className="p-pick-button" onClick={() => setPick('destination')} aria-label="Choose destination on map"><Icon name="pin" size={14} /></button></label><button className="p-button primary" disabled={busy}>{busy ? "Calculating…" : "Calculate corridor"}<Icon name="route" /></button></form>{error && <p className="p-inline-error" role="alert">{error}</p>}<div className="p-emergency-layout"><div><div ref={mapSection} className="p-emergency-map"><CityMap route={route} onPick={pick ? (lat, lng) => { const value = `${lat.toFixed(6)},${lng.toFixed(6)}`; if (pick === 'origin') setOrigin(value); else setDestination(value); setPick(null); } : undefined} />{pick && <div className="p-map-pick-hint">Select the {pick === 'origin' ? "origin" : "destination"}  on the map<button onClick={() => setPick(null)}>Cancel</button></div>}<div className="p-route-key"><span><i className="green" />Primary route</span><span><i className="amber" />Backup route</span></div></div><Panel title="Cameras near the corridor" action={<small>Proximity ≤ 700 m</small>}>{route ? checkpoints.length ? <div className="p-checkpoint-strip">{checkpoints.map((camera, i) => <div key={camera.id}><span className="p-checkpoint-label"><i>{i + 1}</i>{camera.name}</span><CameraThumb camera={camera} /><small>Video source · open to connect</small></div>)}</div> : <p className="p-small-note">No public cameras are registered within 700 m of this route.</p> : <EmptyState title="Calculate a route to check coverage" detail="Camera proximity does not confirm road conditions." />}</Panel></div><aside><Panel title="Route intelligence">{route ? <><div className="p-route-eta"><small>Engine estimated time</small><strong>{eta?.toFixed(1)}<span>min</span></strong><p>{(route.total_distance_m / 1000).toFixed(2)} km · {route.path_node_ids.length}  nodes</p></div><div className="p-route-assessment"><span>Topological continuity</span><b>{assessment?.score_pct ?? '—'}{assessment ? '%' : ''}</b><p>{assessment?.explanation || "No backup assessment available."}</p><small>This score measures overlap and detour; it is not an arrival probability.</small></div><div className="p-route-options">{options.map((option, i) => <button key={option.route_id} className={route.route_id === option.route_id ? 'selected' : ''} onClick={() => useStore.getState().setActiveRoute(option)}><span>{i === 0 ? "Primary" : `Backup ${i}`}<b>{(option.total_estimated_time_s / 60).toFixed(1)} min</b></span><small>{(option.total_distance_m / 1000).toFixed(2)}  km · view route</small></button>)}</div></> : <EmptyState title="Plan the journey" detail="Select an origin and destination within the Downtown Los Angeles network." />}</Panel><Panel title="Next check"><p className="p-detail-description">Query corridor cameras and confirmed closures before choosing a route.</p><button className="p-button" onClick={() => useProduct.getState().navigate('/risk-signals')}>Review signals <Icon name="arrow" /></button></Panel><div className="p-decision-notice"><Icon name="shield" size={22} /><p>Decision support for authorized operators. Estimates use graph speeds without live calibration. It does not dispatch units or control traffic signals.</p></div></aside></div></div>;

}

export function Cameras({ onConnect, onRetry }: { onConnect: () => void; onRetry: () => void }) {
  const district = useProduct((s) => s.district);
  const cameras = useProduct((s) => s.cameras);
  const catalogLoaded = useProduct((s) => s.cameraCatalogLoaded);
  const catalogFailed = useProduct((s) => s.cameraCatalogFailed);
  const catalogStatus = cameraCatalogStatus(cameras.length, catalogLoaded, catalogFailed);
  const query = useProduct((s) => s.query);
  const [filter, setFilter] = useState('all');
  const [zoneCoverage, setZoneCoverage] = useState<{ video_camera_count: number; calibrated_count: number; calibration_required_count: number; zone_required_count: number; route_metadata_required_count: number; cameras: { camera_id: string; zone_enabled: boolean; zone_revision: number; route_metadata_available: boolean; ready_for_road_analysis: boolean; status: string }[] } | null>(null);
  const favorites = useProduct((s) => s.favoriteCameras);
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const [order, setOrder] = useState('recommended');
  const gallery = useRef<HTMLDivElement>(null);
  const [page, setPage] = useState(0);
  const scope = `${district}-${filter}-${query}-${favoritesOnly}-${order}`;
  const [pageScope, setPageScope] = useState(scope);
  useEffect(() => {
    const controller = new AbortController();
    fetch(apiUrl('/api/v1/mobility/video/analysis-zones'), { signal: controller.signal })
      .then(response => response.ok ? response.json() : Promise.reject(new Error('Zone coverage unavailable')))
      .then((value: typeof zoneCoverage) => setZoneCoverage(value))
      .catch(() => { if (!controller.signal.aborted) setZoneCoverage(null); });
    return () => controller.abort();
  }, [cameras.length]);
  const zoneByCamera = new Map((zoneCoverage?.cameras || []).map(zone => [zone.camera_id, zone]));
  const visible = cameras.filter((c) => (!favoritesOnly || favorites.includes(c.id)) && matchesZone(district, c.district) && `${c.name} ${c.provider} ${c.id} ${c.district} ${c.route || ''}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'all' || filter === 'checked-video' && c.stream_url && hasPreviouslyVerifiedVideo(c) || filter === 'needs-calibration' && c.stream_url && zoneByCamera.get(c.id)?.ready_for_road_analysis === false)).sort((a, b) => order === 'name' ? a.name.localeCompare(b.name) : order === 'city' ? a.district.localeCompare(b.district) || a.name.localeCompare(b.name) : Number(favorites.includes(b.id)) - Number(favorites.includes(a.id)));
  const currentPage = pageScope === scope ? Math.min(page, Math.max(0, Math.ceil(visible.length / 12) - 1)) : 0;
  const pageItems = visible.slice(currentPage * 12, currentPage * 12 + 12);
  const navigatePage = (next: number) => { setPageScope(scope); setPage(next); gallery.current?.scrollIntoView({ block: 'start', behavior: 'auto' }); };
  const nextZoneCamera = nextCalibrationCamera(cameras, zoneCoverage?.cameras || []);
  const corridorProgress = calibrationCorridorProgress(cameras, zoneCoverage?.cameras || []);
  const pendingPlayback = calibrationPlaybackCoverage(cameras.filter(camera => camera.stream_url
    && zoneByCamera.get(camera.id)?.ready_for_road_analysis !== true));
  const startCalibrationQueue = () => {
    setFilter('needs-calibration');
    setFavoritesOnly(false);
    if (nextZoneCamera) useProduct.getState().navigate('/cameras/' + nextZoneCamera.id + '?calibrate=road&queue=1');
  };
  return <div className="p-screen"><PageHeading eyebrow="WINDOWS INTO THE CITY" title="Public cameras" subtitle="California · Caltrans video sources with continuous vehicle tracking." action={<><button className="p-button" onClick={() => useProduct.getState().navigate('/explore')}><Icon name="map" />Explore by street</button><button className="p-button primary" onClick={onConnect}><Icon name="plus" />Connect a source</button></>} /><div className="p-camera-intro"><Icon name="shield" size={24} /><p><b>A real source. A verifiable observation.</b>  Open a camera to watch continuous video with vehicle tracking. Source availability is checked when you connect.</p><a className="p-text-button" href="https://quickmap.dot.ca.gov/" target="_blank" rel="noreferrer">Caltrans QuickMap <Icon name="arrow" size={14} /></a></div><div className="p-region-explorer" aria-label="Catalog areas"><button className={district === "All districts" ? 'active' : ''} onClick={() => useProduct.getState().setDistrict("All districts")}>Entire region <b>{cameras.length}</b></button>{regions.map(region => <button key={region.name} className={district === region.name ? 'active' : ''} onClick={() => { useProduct.getState().setDistrict(region.name); }}> {region.name}<b>{cameras.filter(c => matchesZone(region.name, c.district)).length}</b></button>)}</div><div className="p-regional-summary"><strong>Public Caltrans access</strong>Registered sources may show temporary notices. A registered link does not guarantee playback. Open the camera to establish a video session.</div>{zoneCoverage && zoneCoverage.calibration_required_count > 0 && <div className="p-calibration-banner" role="status"><div><span className="p-eyebrow">DIRECTIONAL ROAD ANALYSIS</span><strong>{zoneCoverage.calibrated_count} of {zoneCoverage.video_camera_count} video cameras ready for road analysis</strong><p>Only cameras with a reviewed zone, route and travel direction can contribute directional traffic estimates. {zoneCoverage.zone_required_count} camera zones need review; {zoneCoverage.route_metadata_required_count} lack route/direction metadata. {pendingPlayback.previouslyVerified} pending feeds previously returned HLS 200 and require live lane review; {pendingPlayback.playbackCheckRequired} require playback verification first.</p><details className="p-corridor-calibration"><summary><span>Route and direction progress</span><small>{corridorProgress.filter(group => group.pending > 0).length} corridors need review</small></summary><div className="p-corridor-progress-list">{corridorProgress.filter(group => group.pending > 0).map(group => { const camera = group.next_camera; return <div className="p-corridor-progress-row" key={group.key}><div><b>{group.route} · {group.direction}</b><small>{group.ready} of {group.total} cameras ready</small></div>{camera && <button className="p-text-button" aria-label={`Review next camera on ${group.route} ${group.direction}: ${camera.name}`} onClick={() => useProduct.getState().navigate(`/cameras/${camera.id}?calibrate=road&queue=1`)}>Review next <span>{camera.name}</span></button>}</div>; })}</div></details></div><div className="p-calibration-actions"><button className="p-button primary" disabled={!nextZoneCamera} onClick={startCalibrationQueue}>{nextZoneCamera ? 'Start calibration queue' : 'No video sources to calibrate'} <Icon name="arrow" size={15} /></button><button className="p-button" onClick={() => { setFilter('needs-calibration'); setFavoritesOnly(false); }}>Review camera list</button></div></div>}<div className="p-filter-bar"><label>Video link<select value={filter} onChange={(e) => setFilter(e.target.value)}><option value="all">All registered video sources</option><option value="checked-video">HLS URL returned HTTP 200 previously</option><option value="needs-calibration">Needs road calibration</option></select></label><label>Sort by<select value={order} onChange={e => setOrder(e.target.value)}><option value="recommended">Favorites first</option><option value="name">Name</option><option value="city">City</option></select></label><button className={`p-button ${favoritesOnly ? 'primary' : ''}`} aria-pressed={favoritesOnly} onClick={() => setFavoritesOnly(!favoritesOnly)}><Icon name="star" size={16} />My favorites ({favorites.filter(id => cameras.some(c => c.id === id)).length})</button><span className="p-filter-count" role="status">{visible.length} cameras</span><span className="p-small-note">Continuous video · no photo fallback.</span></div><div ref={gallery} className="p-camera-grid">{pageItems.map((camera, i) => { const zone = zoneByCamera.get(camera.id); const autoOpenCalibration = hasPreviouslyVerifiedVideo(camera); return <article key={camera.id} className="p-camera-tile"><CameraThumb camera={camera} /><div><span className="p-eyebrow">{camera.provider} · {String(currentPage * 12 + i + 1).padStart(2, '0')}</span><h3>{camera.name}</h3><p><Icon name="pin" size={12} />{camera.district}</p><p className="p-camera-status-note"><Badge tone={cameraStatus(camera).tone}>{cameraStatus(camera).label}</Badge><small>{checkedAt(camera.last_observed_at || camera.verified_at)}</small></p>{zoneCoverage && camera.stream_url && <p className="p-camera-zone-note"><Badge tone={zone?.ready_for_road_analysis ? 'green' : 'amber'}>{zone?.ready_for_road_analysis ? `Road analysis ready · v${zone.zone_revision}` : zone?.status === 'zone_and_metadata_required' ? 'Zone + route metadata required' : zone?.status === 'route_metadata_required' ? 'Route/direction metadata required' : 'Direction zone required'}</Badge></p>}{zoneCoverage && camera.stream_url && !zone?.ready_for_road_analysis && <><button className="p-text-button p-calibration-action" onClick={() => useProduct.getState().navigate(`/cameras/${camera.id}${autoOpenCalibration ? '?calibrate=road' : ''}`)}><Icon name="camera" size={14} />{autoOpenCalibration ? 'Watch video and set direction zone' : 'Check live video before calibration'}</button>{!autoOpenCalibration && <small className="p-camera-calibration-note">Calibration tools open from the live video after playback is confirmed.</small>}{zone?.status === 'zone_and_metadata_required' && <small className="p-camera-calibration-note">Route and direction metadata also need review.</small>}</>}<button className="p-favorite-button" aria-label={`${favorites.includes(camera.id) ? "Remove from favorites" : "Save favorite"}: ${camera.name}`} aria-pressed={favorites.includes(camera.id)} onClick={() => useProduct.getState().toggleFavorite(camera.id)}><Icon name="star" size={17} />{favorites.includes(camera.id) ? "Saved" : "Save"}</button><footer><Badge tone="gray">{camera.stream_url ? hasPreviouslyVerifiedVideo(camera) ? "HLS URL responded previously · playback unconfirmed" : "Video not yet verified" : "Video not supported"}</Badge><button className="p-text-button" onClick={() => useProduct.getState().navigate(`/cameras/${camera.id}`)}>Open evidence <Icon name="arrow" size={15} /></button></footer></div></article>; })}</div>{visible.length > 12 && <div className="p-catalog-pagination"><button className="p-button" disabled={currentPage === 0} onClick={() => navigatePage(currentPage - 1)}>Previous</button><span role="status">{currentPage * 12 + 1} - {Math.min((currentPage + 1) * 12, visible.length)} of {visible.length}</span><button className="p-button" disabled={(currentPage + 1) * 12 >= visible.length} onClick={() => navigatePage(currentPage + 1)}>Next</button></div>}{!visible.length && catalogStatus === 'loading' && <EmptyState title="Loading cameras" detail="Connecting to the camera catalog. The source list will appear here shortly." />}{!visible.length && catalogStatus === 'error' && <EmptyState title="Camera catalog unavailable" detail="The camera service could not be reached. Retry to reload the registered video sources." action={<button className="p-button primary" onClick={onRetry}>Retry camera connection</button>} />}{!visible.length && catalogStatus === 'empty' && <EmptyState title="No video sources registered" detail="Connect a public video source or retry after checking the camera service." action={<button className="p-button primary" onClick={onConnect}><Icon name="plus" />Connect a source</button>} />}{!visible.length && catalogStatus === 'ready' && <EmptyState title="No registered sources for this filter" detail="The catalog covers seven metropolitan areas. Change the filters to broaden your search." action={<button className="p-button" onClick={() => { setFilter('all'); setFavoritesOnly(false); useProduct.getState().setDistrict("All districts"); useProduct.getState().setQuery(''); }}>View the entire catalog</button>} />}</div>;

}

export function ConnectDialog({ onClose }: { onClose: () => void }) {

  const dialog = useRef<HTMLDialogElement>(null);
  const [name, setName] = useState(''); const [source, setSource] = useState('');
  const [lat, setLat] = useState('34.048'); const [lng, setLng] = useState('-118.259');
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  useEffect(() => { dialog.current?.showModal(); }, []);
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try { const camera = await connectCamera({ name, source, lat: Number(lat), lng: Number(lng) }); useProduct.getState().setCameras(await getCameras()); useProduct.getState().notify("Video source connected: consecutive frames were decoded."); onClose(); useProduct.getState().navigate(`/cameras/${camera.id}`); }
    catch (error) { setError(error instanceof Error ? error.message : "Could not connect."); }
    finally { setBusy(false); }
  };
  return <dialog ref={dialog} className="p-dialog" onCancel={onClose}><form onSubmit={(event) => void submit(event)}><header><span className="p-eyebrow">NEW SOURCE</span><button type="button" className="p-icon-button" aria-label="Close connection dialog" onClick={onClose}><Icon name="close" /></button><h2>Connect a camera</h2><p>The connection is saved after continuous video decoding is verified.</p></header><label>Name<input autoFocus required minLength={2} value={name} onChange={(e) => setName(e.target.value)} placeholder="Corridor access point" /></label><label>HTTP(S) video stream, RTSP or webcam index<input required value={source} onChange={(e) => setSource(e.target.value)} placeholder="https://…/playlist.m3u8 or 0" /></label><div className="p-form-two"><label>Latitude<input required type="number" step="any" min="-90" max="90" value={lat} onChange={(e) => setLat(e.target.value)} /></label><label>Longitude<input required type="number" step="any" min="-180" max="180" value={lng} onChange={(e) => setLng(e.target.value)} /></label></div><p className="p-small-note">Connect a source you are authorized to query. Do not include passwords in the URL. RTSP and webcams are read from the machine running FlowSense.</p>{error && <p className="p-inline-error" role="alert">{error}</p>}<footer><button type="button" className="p-button" onClick={onClose}>Cancel</button><button className="p-button primary" disabled={busy}>{busy ? "Checking video…" : "Check and connect"}<Icon name="arrow" /></button></footer></form></dialog>;

}

export function Reports() {

  const cases = useProduct((s) => s.cases);
  const mode = useProduct((s) => s.mode);
  const [type, setType] = useState("Operational situation");
  const period = useProduct((s) => s.period);
  return <div className="p-screen p-reports"><PageHeading eyebrow="SHAREABLE EVIDENCE" title="From analysis to report" subtitle="Export what was reviewed, its provenance and the next steps." action={<Badge tone="gray">{cases.length}  registered cases</Badge>} /><div className="p-report-layout"><section><div className="p-report-type-grid">{[["Operational situation", 'map', "The city and its sources at a glance."], ["Corridor", 'route', "Trends, context and baseline."], ["Risk review", 'alert', "Cases, decisions and audit log."]].map(([name, icon, description]) => <button key={name} className={type === name ? 'selected' : ''} onClick={() => setType(name)}><Icon name={icon} size={26} /><h3>{name}</h3><p>{description}</p></button>)}</div><Panel title="Cases and decisions"><div className="p-table-scroll">{cases.length ? <table className="p-table"><thead><tr><th>Case</th><th>Title</th><th>Team</th><th>Status</th><th>Provenance</th></tr></thead><tbody>{cases.map((item) => <tr key={item.id}><td><b>{item.id}</b></td><td>{item.title}</td><td>{item.owner}</td><td><ReviewBadge value={item.status} /></td><td>{item.data_origin === 'presentation' ? "Scenario" : "Observation"}</td></tr>)}</tbody></table> : <EmptyState title="No cases have been opened yet" detail="Assign a review from Hotspots or Risk signals." action={<button className="p-button" onClick={() => useProduct.getState().navigate('/risk-signals')}>Open review queue <Icon name="arrow" /></button>} />}</div></Panel><section className="p-print-report"><BrandMark size={48} /><h2>FlowSense · {type}</h2><p>Los Angeles, California · {period} · {new Date().toLocaleString("en-US")}</p><p>Mode: {mode === 'presentation' ? "illustrative scenario" : "observations"}. Cameras: Caltrans. Road network: OpenStreetMap.</p><p>Scenario indicators do not establish current conditions or pilot impact.</p>{cases.map((c) => <article key={c.id}><h3>{c.id} · {c.title}</h3><p>{statusLabels[c.status]} · {c.owner}  · provenance: {c.data_origin}</p>{c.audit.map((a, i) => <p key={i}>{a.at} · {a.action} · {a.owner} · {a.note}</p>)}</article>)}</section></section><aside><Panel title="Prepare export"><label className="p-report-field">Content<select value={type} onChange={(e) => setType(e.target.value)}>{["Operational situation", "Corridor", "Risk review"].map((name) => <option key={name}>{name}</option>)}</select></label><div className="p-report-summary"><span>Period<b>{period}</b></span><span>Region<b>Los Angeles, CA</b></span><span>Cases<b>{cases.length}</b></span><span>Video source<b>Caltrans · public</b></span><span>Indicators<b>{mode === 'presentation' ? "Illustrative" : "Observed"}</b></span></div><a className="p-button primary" href={apiUrl('/api/v1/mobility/reports/cases.csv')} download><Icon name="download" />Export cases CSV</a><a className="p-button" href={apiUrl(`/api/v1/mobility/reports/cases.pdf?title=${encodeURIComponent(type)}&period=${encodeURIComponent(period)}`)} download><Icon name="download" />Download PDF</a><button className="p-button" onClick={() => window.print()}><Icon name="report" />Print / save PDF</button><button className="p-button" disabled={mode !== 'presentation'} onClick={() => downloadCsv('flowsense-analytics.csv', trendSeries().map((row) => ({ report_type: type, period, district: useProduct.getState().district, data_origin: 'presentation', ...row })))}><Icon name="chart" />Export analytics CSV</button><p className="p-small-note">The report includes the source, provenance and audit log. Download the PDF directly or use browser printing.</p></Panel><Panel title="Before and after"><p className="p-detail-description">Measuring real impact requires a baseline, an implemented intervention and comparable traffic counts. The scenario shows the format; it does not establish municipal improvement.</p></Panel></aside></div></div>;

}

export function Storyboard() {

  const steps = [ ['camera', '01', "Public cameras", "Continuous video", "Query free Caltrans sources or connect an authorized camera.", '/cameras'], ['search', '02', "Detection + evidence", "Vehicles tracked in motion", "OpenCV detects classes and draws aligned boxes. No personal identification.", '/cameras'], ['chart', '03', "Mobility metrics", "Context over time", "Observed counts and illustrative series are clearly distinguished.", '/corridors/harbor'], ['map', '04', "City intelligence", "Prioritize where to look", "The map connects segments, hotspots, cameras and context.", '/overview'], ['shield', '05', "Human review", "The decision is documented", "Assign, review and confirm a case. Every step is recorded in the audit log.", '/risk-signals'], ['report', '06', "Action + report", "Close the loop", "Share the evidence and define the next check.", '/reports'] ];
  return <div className="p-screen p-storyboard"><PageHeading eyebrow="FROM VIDEO TO A BETTER DECISION" title="How FlowSense works." subtitle="One platform. Multiple questions about the city." action={<button className="p-button primary" onClick={() => { useProduct.getState().setMode('presentation'); useProduct.getState().selectSignal('SIG-001'); useProduct.getState().setDemoIndex(0); useProduct.getState().navigate('/overview'); }}>Start tour <Icon name="play" /></button>} /><div className="p-pipeline">{steps.map(([icon, number, title, sub, detail, route]) => <button key={number} onClick={() => useProduct.getState().navigate(route)}><span className="p-pipeline-number">{number}</span><div className="p-pipeline-icon"><Icon name={icon} size={30} /></div><h2>{title}</h2><b>{sub}</b><p>{detail}</p><span className="p-text-button">Explore module <Icon name="arrow" size={16} /></span></button>)}</div><h2 className="p-modes-title">Evidence has more than one application.</h2><div className="p-story-modes">{[['route', "Corridors", "Diagnose trends and access points.", '/corridors/harbor'], ['walk', "Pedestrian flow", "Review crossings and aggregate demand.", '/pedestrians'], ['alert', "Risk signals", "Prioritize reviews without automatic confirmation.", '/risk-signals'], ['camera', "Emergencies", "Compare a corridor and its backup.", '/emergency-corridor']].map(([icon, title, desc, route]) => <button key={title} onClick={() => useProduct.getState().navigate(route)}><Icon name={icon} size={28} /><h3>{title}</h3><p>{desc}</p><Icon name="arrow" size={18} /></button>)}</div><div className="p-story-principle"><BrandMark size={40} decorative /><div><h3>More clarity. Better questions.</h3><p>FlowSense organizes the evidence. The operator validates the context and decides the next action.</p></div></div></div>;

}

export function Settings({ onConnect }: { onConnect: () => void }) {

  const cameras = useProduct((s) => s.cameras); const mode = useProduct((s) => s.mode);
  const graph = useStore((s) => s.graphStatus);
  return <div className="p-screen"><PageHeading eyebrow="SOURCES AND PREFERENCES" title="Settings" subtitle="Control the view context and check where the data comes from." /><ThemeSettings /><div className="p-settings-layout"><Panel title="Working mode"><div className="p-setting-option"><div><h3>Presentation scenario</h3><p>Reproducible examples to explore every screen and practice a review.</p></div><input type="radio" name="data-mode" aria-label="Use presentation scenario" checked={mode === 'presentation'} onChange={() => useProduct.getState().setMode('presentation')} /></div><div className="p-setting-option"><div><h3>Available observations</h3><p>Views show only verified measurements. Missing history appears as unavailable data.</p></div><input type="radio" name="data-mode" aria-label="Use observations" checked={mode === 'observed'} onChange={() => useProduct.getState().setMode('observed')} /></div></Panel><Panel title="Road network and coverage"><div className="p-health-rows"><span>Profile<b>{graph?.city || "Querying…"}</b></span><span>Graph source<b>{graph?.is_synthetic ? "Synthetic" : 'OpenStreetMap'}</b></span><span>Nodes<b>{graph?.node_count.toLocaleString("en-US") || '—'}</b></span><span>Segments<b>{graph?.edge_count.toLocaleString("en-US") || '—'}</b></span><span>Public sources<b>{cameras.length}</b></span></div><button className="p-button primary" onClick={onConnect}><Icon name="plus" />Connect a source</button></Panel><Panel title="Privacy and review"><p className="p-detail-description">Observations are aggregated by class and frame. People and drivers are not identified. Public video may contain people or license plates; anonymization is not guaranteed.</p><p className="p-small-note">There is no automatic traffic signal control or autonomous dispatch. Cases record the operator's decisions.</p></Panel><Panel title="Public sources"><a className="p-source-link" href="https://cwwp2.dot.ca.gov/documentation/cctv/cctv.htm" target="_blank" rel="noreferrer">Caltrans · CCTV documentation <Icon name="arrow" /></a><a className="p-source-link" href="https://quickmap.dot.ca.gov/" target="_blank" rel="noreferrer">Caltrans QuickMap <Icon name="arrow" /></a><a className="p-source-link" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap · attribution <Icon name="arrow" /></a></Panel></div></div>;

}
